cd /home/claude && python3 - << 'PY'
import re
orig=open("/home/claude/drive/LOWDIN-ORIGINAL.txt",encoding="utf-8").read()
tree=open("/home/claude/build/THE-LOWDIN-SOLUTION-2.md",encoding="utf-8").read()
ch35=open("/home/claude/build/The_Method_1_6-2.md",encoding="utf-8").read()

def nums(t):
    return set(re.findall(r'\d[\d,]*\.?\d*', t.replace('\u2212','-')))
def norm(s): return s.replace(',','').rstrip('.')

o={norm(x) for x in nums(orig)}
tr={norm(x) for x in nums(tree)}
missing=sorted(o-tr, key=lambda s:(len(s),s))
print("distinct numbers in ORIGINAL:",len(o),"| in TREE paper:",len(tr))
print("in ORIGINAL, absent from TREE paper:",len(missing))
# only report the ones that are also absent from the whole main volume
notmain=[m for m in missing if m not in {norm(x) for x in nums(ch35)}]
print("...and also absent from the MAIN VOLUME:",len(notmain))
print()
for m in notmain:
    if len(m)<2: continue
    for line in orig.split("\n"):
        if m in line.replace(',',''):
            print(f"  {m:>12}  |  {line.strip()[:95]}"); break
PY

